-- Chat censor: slurs and hate become #####. Ordinary swearing (fuck, damn, shit, kut...) is fine.
-- Generated by scripts/build-censor.mjs from scripts/censor-list.mjs (the same list the game uses).
-- Applies to chat messages, player and company names, and profile names.
create or replace function public.censor_text(t text) returns text language plpgsql immutable set search_path = '' as $$
declare p text; out text := t;
begin
  if out is null or out = '' then return out; end if;
  foreach p in array array[
    $re$n+[._*~\-]*[i1!|l]+[._*~\-]*[g9]+[._*~\-]*[g9]+(?!l)(?:[._*~\-]*\w)*$re$,
    $re$\yn+[._*~\-]*[i1!|l]+[._*~\-]*k+[._*~\-]*k+[._*~\-]*[e3]+[._*~\-]*r+(?:[._*~\-]*\w)*$re$,
    $re$n+[._*~\-]*[i1!|l]+[._*~\-]*[g9]+[._*~\-]*l+[._*~\-]*[e3]+[._*~\-]*[t7]+$re$,
    $re$\yn+[._*~\-]*[e3]+[._*~\-]*[g9]+[._*~\-]*r+[._*~\-]*[o0]+(es)?\y$re$,
    $re$\yc+[._*~\-]*h+[._*~\-]*[i1!|l]+[._*~\-]*n+[._*~\-]*k+s?\y$re$,
    $re$\y[g9]+[._*~\-]*[o0]+[._*~\-]*[o0]+[._*~\-]*k+s?\y$re$,
    $re$\y[s5$]+[._*~\-]*p+[._*~\-]*[i1!|l]+[._*~\-]*c+s?\y$re$,
    $re$\yk+[._*~\-]*[i1!|l]+[._*~\-]*k+[._*~\-]*[e3]+s?\y$re$,
    $re$w+[._*~\-]*[e3]+[._*~\-]*[t7]+[._*~\-]*[b8]+[._*~\-]*[a4@]+[._*~\-]*c+[._*~\-]*k+s?$re$,
    $re$\yc+[._*~\-]*[o0]+[._*~\-]*[o0]+[._*~\-]*n+s?\y$re$,
    $re$\yp+[._*~\-]*[a4@]+[._*~\-]*k+[._*~\-]*[i1!|l]+s?\y$re$,
    $re$[t7]+[._*~\-]*[o0]+[._*~\-]*w+[._*~\-]*[e3]+[._*~\-]*l+[._*~\-]*h+[._*~\-]*[e3]+[._*~\-]*[a4@]+[._*~\-]*d+s?$re$,
    $re$r+[._*~\-]*[a4@]+[._*~\-]*[g9]+[._*~\-]*h+[._*~\-]*[e3]+[._*~\-]*[a4@]+[._*~\-]*d+s?$re$,
    $re$j+[._*~\-]*[i1!|l]+[._*~\-]*[g9]+[._*~\-]*[a4@]+[._*~\-]*[b8]+[._*~\-]*[o0]+[._*~\-]*[o0]+s?$re$,
    $re$\y[b8]+[._*~\-]*[e3]+[._*~\-]*[a4@]+[._*~\-]*n+[._*~\-]*[e3]+[._*~\-]*r+s?\y$re$,
    $re$p+[._*~\-]*[o0]+[._*~\-]*r+[._*~\-]*c+[._*~\-]*h+[._*~\-]*\s*[._*~\-]*m+[._*~\-]*[o0]+[._*~\-]*n+[._*~\-]*k+[._*~\-]*[e3]+[._*~\-]*y+s?$re$,
    $re$j+[._*~\-]*u+[._*~\-]*n+[._*~\-]*[g9]+[._*~\-]*l+[._*~\-]*[e3]+[._*~\-]*\s*[._*~\-]*[b8]+[._*~\-]*u+[._*~\-]*n+[._*~\-]*n+[._*~\-]*y+$re$,
    $re$[s5$]+[._*~\-]*[a4@]+[._*~\-]*n+[._*~\-]*d+[._*~\-]*\s*[._*~\-]*m+[._*~\-]*[o0]+[._*~\-]*n+[._*~\-]*k+[._*~\-]*[e3]+[._*~\-]*y+$re$,
    $re$[z2]+[._*~\-]*[i1!|l]+[._*~\-]*p+[._*~\-]*p+[._*~\-]*[e3]+[._*~\-]*r+[._*~\-]*h+[._*~\-]*[e3]+[._*~\-]*[a4@]+[._*~\-]*d+s?$re$,
    $re$f+[._*~\-]*[a4@]+[._*~\-]*[g9]+[._*~\-]*[g9]+[._*~\-]*[o0]+[._*~\-]*[t7]+s?$re$,
    $re$\yf+[._*~\-]*[a4@]+[._*~\-]*[g9]+[._*~\-]*[o0]+[._*~\-]*[t7]+s?\y$re$,
    $re$\yf+[._*~\-]*[a4@]+[._*~\-]*[g9]+s?\y$re$,
    $re$\y[t7]+[._*~\-]*r+[._*~\-]*[a4@]+[._*~\-]*n+[._*~\-]*n+[._*~\-]*y+\y$re$,
    $re$\y[t7]+[._*~\-]*r+[._*~\-]*[a4@]+[._*~\-]*n+[._*~\-]*n+[._*~\-]*[i1!|l]+[._*~\-]*[e3]+[._*~\-]*[s5$]+\y$re$,
    $re$n[e3]g[e3]r(?!en|end)\w*$re$,
    $re$n+[._*~\-]*[e3]+[._*~\-]*[g9]+[._*~\-]*[e3]+[._*~\-]*r+[._*~\-]*[i1!|l]+[._*~\-]*n+$re$,
    $re$\ym+[._*~\-]*[a4@]+[._*~\-]*k+[._*~\-]*[a4@]+[._*~\-]*[a4@]+[._*~\-]*k+(en)?\y$re$,
    $re$\yf+[._*~\-]*l+[._*~\-]*[i1!|l]+[._*~\-]*k+[._*~\-]*k+[._*~\-]*[e3]+[._*~\-]*r+s?\y$re$,
    $re$(kanker|kut|vuile|rot|tering)\s*(jo+de?n?|marok\w*|turk\w*|zigeuner\w*|homo\w*)$re$,
    $re$h+[._*~\-]*[e3]+[._*~\-]*[i1!|l]+[._*~\-]*l+[._*~\-]*\s*[._*~\-]*h+[._*~\-]*[i1!|l]+[._*~\-]*[t7]+[._*~\-]*l+[._*~\-]*[e3]+[._*~\-]*r+$re$,
    $re$[s5$]+[._*~\-]*[i1!|l]+[._*~\-]*[e3]+[._*~\-]*[g9]+[._*~\-]*\s*[._*~\-]*h+[._*~\-]*[e3]+[._*~\-]*[i1!|l]+[._*~\-]*l+$re$,
    $re$gas\s+(the|de|alle)\s+jo?(ews|oden)$re$,
    $re$white\s+power$re$,
    $re$\y1488\y$re$
  ] loop
    out := regexp_replace(out, p, '#####', 'gi');
  end loop;
  return out;
end $$;

create or replace function public._censor_row() returns trigger language plpgsql set search_path = '' as $$
begin
  if tg_table_name = 'messages' then new.body := public.censor_text(new.body);
  elsif tg_table_name = 'players' then new.player_name := public.censor_text(new.player_name); new.company_name := public.censor_text(new.company_name);
  elsif tg_table_name = 'profiles' then new.name := public.censor_text(new.name);
  end if;
  return new;
end $$;
revoke execute on function public._censor_row() from public, anon, authenticated;

drop trigger if exists messages_censor on public.messages;
create trigger messages_censor before insert or update of body on public.messages for each row execute function public._censor_row();
drop trigger if exists players_censor on public.players;
create trigger players_censor before insert or update of player_name, company_name on public.players for each row execute function public._censor_row();
drop trigger if exists profiles_censor on public.profiles;
create trigger profiles_censor before insert or update of name on public.profiles for each row execute function public._censor_row();
